def solve(inputs: dict) -> float:
    base = inputs.get('base', inputs.get('a', inputs.get('number')))
    exponent = inputs.get('exponent', inputs.get('power', inputs.get('b')))
    modulus = inputs.get('modulus', inputs.get('mod', inputs.get('m')))
    if base is None or exponent is None or modulus is None:
        nums = list(inputs.values())
        if len(nums) != 3:
            raise ValueError('Expected base, exponent, and modulus')
        base, exponent, modulus = nums
    return pow(int(base), int(exponent), int(modulus))

