def solve(inputs: dict) -> float:
    terms = inputs.get('terms', inputs.get('continued_fraction', inputs.get('coefficients')))
    if terms is None:
        if len(inputs) != 1:
            raise ValueError('Expected a list of continued-fraction terms')
        terms = next(iter(inputs.values()))
    p_prev, p = 0, 1
    for a in terms:
        p_prev, p = p, int(a) * p + p_prev
    return p

